@@ -16,4 +16,8 @@
 #include <vector>

+#if FMT_CPLUSPLUS >= 202002L && FMT_HAS_INCLUDE(<ranges>)
+#  include <ranges>
+#endif
+
 #include "gtest/gtest.h"
@@ -423,3 +427,70 @@
 TEST(ranges_test, vector_char) {
   EXPECT_EQ(fmt::format("{}", std::vector<char>{'a', 'b'}), "['a', 'b']");
 }
+
+struct prvalue_range {
+  struct iterator {
+    int index;
+
+    auto operator*() const -> non_const_only_range<char> {
+      return non_const_only_range<char>(1u, 'a');
+    }
+    void operator++() { ++index; }
+    auto operator!=(const iterator& other) const -> bool {
+      return index != other.index;
+    }
+  };
+
+  auto begin() const -> iterator { return {0}; }
+  auto end() const -> iterator { return {2}; }
+};
+
+TEST(ranges_test, format_prvalue_range) {
+  EXPECT_EQ(fmt::format("{}", prvalue_range()), "[['a'], ['a']]");
+}
+
+#ifdef __cpp_lib_ranges
+TEST(ranges_test, format_split_view) {
+  std::string line = "a,b-c,d-e,f";
+  EXPECT_EQ(fmt::format("{}", line | std::views::split(',')),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+}
+
+struct non_const_string_range {
+  std::string_view sv;
+
+  template <std::ranges::range R>
+  non_const_string_range(R&& r)
+      : sv(std::ranges::data(r), std::ranges::size(r)) {}
+
+  auto begin() { return sv.begin(); }
+  auto end() { return sv.end(); }
+};
+
+TEST(ranges_test, format_transform_view) {
+  std::string line = "a,b-c,d-e,f";
+  auto parts = line | std::views::split(',') |
+               std::views::transform(
+                   [](auto part) { return non_const_string_range(part); });
+  EXPECT_EQ(fmt::format("{}", parts),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+}
+
+TEST(ranges_test, format_nested_split_view) {
+  std::string line = "a,b-c,d-e,f";
+  auto parts = line | std::views::split(',') |
+               std::views::transform(std::views::split('-'));
+  EXPECT_EQ(fmt::format("{}", parts),
+            "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]");
+}
+#endif  // __cpp_lib_ranges
